import unittest
from candidate import will_it_fly

class TestWillItFly(unittest.TestCase):
    def test_normal_balanced_within_weight(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_normal_unbalanced_below_weight(self):
        self.assertFalse(will_it_fly([1, 2], 5))

    def test_normal_balanced_exceeds_weight(self):
        self.assertFalse(will_it_fly([3, 2, 3], 1))

    def test_single_element_true(self):
        self.assertTrue(will_it_fly([3], 5))

    def test_empty_list_true_with_non_negative_weight(self):
        self.assertTrue(will_it_fly([], 0))
        self.assertTrue(will_it_fly([], 10))

    def test_empty_list_false_with_negative_weight(self):
        self.assertFalse(will_it_fly([], -1))

    def test_sum_equals_weight_true(self):
        self.assertTrue(will_it_fly([1, 2, 1], 4))

    def test_sum_exceeds_weight_false(self):
        self.assertFalse(will_it_fly([1, 2, 1], 3))

    def test_non_iterable_q_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly(5, 10)

    def test_none_q_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly(None, 10)

    def test_none_w_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, 2, 1], None)

    def test_w_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, 2, 1], "5")

    def test_negative_weight_false(self):
        self.assertFalse(will_it_fly([1, 1], -1))

    def test_float_elements_true(self):
        self.assertTrue(will_it_fly([1.5, 2.0, 1.5], 5.0))

    def test_float_elements_false_sum_exceeds(self):
        self.assertFalse(will_it_fly([1.5, 2.0, 1.5], 3.9))

    def test_unbalanced_with_floats(self):
        self.assertFalse(will_it_fly([1.5, 2.0, 3.5], 10.0))

    def test_large_palindrome_true(self):
        large = list(range(1000)) + list(range(999, -1, -1))
        self.assertTrue(will_it_fly(large, sum(large)))

    def test_large_palindrome_false_sum_exceeds(self):
        large = list(range(1000)) + list(range(999, -1, -1))
        self.assertFalse(will_it_fly(large, sum(large) - 1))

    def test_no_modification_of_q(self):
        q = [3, 2, 3]
        original = q[:]
        will_it_fly(q, 9)
        self.assertEqual(q, original)

    def test_all_equal_elements_true(self):
        self.assertTrue(will_it_fly([4, 4, 4, 4], 20))

    def test_all_equal_elements_false_weight(self):
        self.assertFalse(will_it_fly([4, 4, 4, 4], 10))

    def test_non_integer_weights_handled(self):
        self.assertTrue(will_it_fly([2, 3, 2], 7.5))
        self.assertFalse(will_it_fly([2, 3, 2], 6.5))

    def test_unbalanced_with_negative_elements(self):
        self.assertFalse(will_it_fly([-1, 0, 1], 5))

    def test_balanced_with_negative_elements_and_weight(self):
        self.assertTrue(will_it_fly([-1, 0, -1], 2))

    def test_balanced_with_negative_sum_and_negative_weight(self):
        self.assertFalse(will_it_fly([-2, -2], -5))

    def test_zero_weight_and_non_empty_list(self):
        self.assertFalse(will_it_fly([1], 0))

    def test_zero_weight_and_empty_list(self):
        self.assertTrue(will_it_fly([], 0))

    def test_non_ascii_elements(self):
        self.assertTrue(will_it_fly(["a", "b", "a"], 10))

    def test_non_ascii_elements_false_sum(self):
        self.assertFalse(will_it_fly(["a", "b", "a"], -10))

    def test_non_ascii_elements_false_unbalanced(self):
        self.assertFalse(will_it_fly(["a", "b", "c"], 10))

if __name__ == "__main__":
    unittest.main()
